"use client";

import { BadgeCheck, Sparkles, Truck } from "lucide-react";

interface AuthBannerProps {
  title: string;
  description: string;
  badge: string;
}

export default function AuthBanner({ title, description, badge }: AuthBannerProps) {
  return (
    <aside className="hidden min-h-[640px] lg:flex">
      <div className="relative flex w-full flex-col overflow-hidden border border-[#d6bd7a]/25 bg-[#0d0b0a] shadow-[0_30px_90px_rgba(0,0,0,0.35)]">
        <div className="relative flex flex-1 items-center bg-[#090706]">
          <img
            src="/images/luxury-perfume-banner.png"
            alt="VANHPERFUME luxury perfume collection"
            className="block h-full w-full object-cover opacity-90"
          />
          <div className="absolute inset-0 bg-gradient-to-r from-black/55 via-black/10 to-black/45" />
          <div className="absolute left-7 top-7 inline-flex items-center gap-2 border border-[#d6bd7a]/55 bg-black/45 px-4 py-2 text-xs font-bold uppercase tracking-[0.22em] text-[#d6bd7a] backdrop-blur">
            <Sparkles className="h-4 w-4" />
            {badge}
          </div>
          <div className="absolute bottom-8 left-8 right-8 max-w-2xl">
            <p className="mb-4 text-xs font-semibold uppercase tracking-[0.35em] text-[#d6bd7a]">Private scent house</p>
            <h2 className="max-w-[680px] font-serif text-4xl font-light leading-tight text-[#f7efe1] xl:text-5xl">
              {title}
            </h2>
            <p className="mt-5 max-w-2xl text-sm leading-7 text-[#eee2cd]/78">
              {description}
            </p>
          </div>
        </div>

        <div className="grid gap-6 border-t border-[#d6bd7a]/18 bg-[#0d0b0a] p-7 xl:grid-cols-[1fr_auto] xl:items-end">
          <div>
            <p className="text-xs font-semibold uppercase tracking-[0.26em] text-[#d6bd7a]">Member privileges</p>
            <p className="mt-3 max-w-2xl text-sm leading-6 text-[#cfc4ad]/75">
              Theo dõi đơn hàng, lưu địa chỉ giao hàng và nhận các gợi ý mùi hương riêng cho phong cách của bạn.
            </p>
          </div>

          <div className="grid gap-3 text-sm text-[#cfc4ad]/78">
            <div className="flex items-center gap-2">
              <BadgeCheck className="h-4 w-4 text-[#d6bd7a]" />
              Ưu đãi thành viên
            </div>
            <div className="flex items-center gap-2">
              <Truck className="h-4 w-4 text-[#d6bd7a]" />
              Giao hàng cẩn trọng
            </div>
          </div>
        </div>
      </div>
    </aside>
  );
}
