"use client";

import { motion } from "framer-motion";
import Link from "next/link";
import type { ReactNode } from "react";
import AuthBanner from "./AuthBanner";

interface AuthFrameProps {
  children: ReactNode;
  bannerBadge: string;
  bannerTitle: string;
  bannerDescription: string;
  mode: "login" | "register" | "forgot" | "change-password";
}

export default function AuthFrame({
  children,
  bannerBadge,
  bannerTitle,
  bannerDescription,
  mode,
}: AuthFrameProps) {
  return (
    <div className="min-h-[calc(100vh-160px)] bg-[#070607] text-[#f7efe1]">
      <div className="mx-auto flex min-h-[calc(100vh-160px)] max-w-[1500px] flex-col px-5 py-10 sm:px-8 lg:px-14">
        <Link
          href="/"
          className="mb-8 inline-flex w-fit items-baseline text-2xl font-semibold tracking-[0.08em] text-[#f7efe1] transition-colors hover:text-[#d6bd7a]"
        >
          VANH<span className="font-serif italic text-[#d6bd7a]">PERFUME</span>
        </Link>

        <motion.div
          key={mode}
          initial={{ opacity: 0, y: 18 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}
          className="grid flex-1 grid-cols-1 items-stretch gap-8 lg:grid-cols-[minmax(360px,520px)_minmax(0,1fr)]"
        >
          <section className="flex min-h-[640px]">{children}</section>

          <AuthBanner
            badge={bannerBadge}
            title={bannerTitle}
            description={bannerDescription}
          />
        </motion.div>
      </div>
    </div>
  );
}
